/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p\\n' | sort && printf '\\n--- tools ---\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
mods=['cv2','PIL','numpy','imageio','moviepy']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',e)
PY"

/bin/bash -lc 'for x in ffmpeg python3 convert identify; do printf "$x: "; command -v "$x" || true; done
python3 - <<'"'PY'
mods=['cv2','PIL','numpy','imageio','moviepy','scipy']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',repr(e))
